		  const length = lengthNode ? num(lengthNode[1]) : 2.54;
		  const rad = at2.rot * Math.PI / 180;
		  const x0 = at2.x - Math.cos(rad) * length;
		  const y0 = at2.y - Math.sin(rad) * length;
		  const a2 = xf2(x0, y0);
		  const b2 = xf2(at2.x, at2.y);
		  sink.push({ type: "line", x1: a2[0], y1: a2[1], x2: b2[0], y2: b2[1], color: "#7dcea0", width: 0.12 });
