		  if (sink.primitives.length === 0) sink.warnings.push("\u7535\u8DEF\u677F\u91CC\u6CA1\u6709\u53EF\u7ED8\u5236\u7684\u8D70\u7EBF\u3001\u5C01\u88C5\u6216\u677F\u6846");
